# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")

def gaps(*texts):
    return find_gaps([parse_span(t) for t in texts], OPEN)

class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        self.assertEqual(
            gaps("09:00-12:00", "13:00-17:00"),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            gaps("10:00-16:30"),
            ["gap 09:00-10:00 (60 min)",
             "gap 16:30-17:00 (30 min)"]
        )

    def test_nothing_worked_is_one_big_gap(self):
        self.assertEqual(
            gaps(), ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        self.assertEqual(gaps("09:00-17:00"), [])

    def test_overlap_and_touching_close_gaps(self):
        found = gaps(
            "09:00-12:00", "11:00-14:00", "14:00-17:00"
        )
        self.assertEqual(found, [])

    def test_order_does_not_matter(self):
        self.assertEqual(
            gaps("13:00-17:00", "09:00-12:00"),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_starting_early_raises(self):
        with self.assertRaises(ValueError):
            gaps("08:00-12:00")

    def test_ending_late_raises(self):
        with self.assertRaises(ValueError):
            gaps("12:00-18:00")

    def test_accepts_any_iterable(self):
        found = find_gaps(iter([Span(540, 600)]), OPEN)
        self.assertEqual(
            found, ["gap 10:00-17:00 (420 min)"]
        )

if __name__ == "__main__":
    unittest.main()
